import * as AvatarPrimitive from "@radix-ui/react-avatar"
import { cva, type VariantProps } from "class-variance-authority"
import * as React from "react"
import { cn } from '@/lib/vert-ui/cn'

const avatarVariants = cva("relative inline-flex shrink-0 overflow-hidden rounded-full", {
  variants: {
    variant: {
      default: "bg-muted text-foreground",
      brand: "bg-brand/15 text-brand",
      surface: "bg-surface text-muted-foreground",
    },
    size: {
      sm: "size-8 text-xs",
      md: "size-10 text-sm",
      lg: "size-12 text-base",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
})

export interface AvatarProps
  extends Omit<React.ComponentPropsWithRef<typeof AvatarPrimitive.Root>, "size">,
    VariantProps<typeof avatarVariants> {}

const Avatar = React.forwardRef<React.ElementRef<typeof AvatarPrimitive.Root>, AvatarProps>(
  ({ className, variant, size, ...props }, ref) => (
    <AvatarPrimitive.Root
      ref={ref}
      data-slot="avatar"
      data-variant={variant || "default"}
      data-size={size || "md"}
      className={cn(avatarVariants({ variant, size }), className)}
      {...props}
    />
  )
)
Avatar.displayName = "Avatar"

const AvatarImage = React.forwardRef<
  React.ElementRef<typeof AvatarPrimitive.Image>,
  React.ComponentPropsWithRef<typeof AvatarPrimitive.Image>
>(({ className, ...props }, ref) => (
  <AvatarPrimitive.Image
    ref={ref}
    data-slot="avatar-image"
    className={cn("size-full object-cover", className)}
    {...props}
  />
))
AvatarImage.displayName = "AvatarImage"

const AvatarFallback = React.forwardRef<
  React.ElementRef<typeof AvatarPrimitive.Fallback>,
  React.ComponentPropsWithRef<typeof AvatarPrimitive.Fallback>
>(({ className, ...props }, ref) => (
  <AvatarPrimitive.Fallback
    ref={ref}
    data-slot="avatar-fallback"
    className={cn(
      "flex size-full items-center justify-center rounded-full font-medium",
      className
    )}
    {...props}
  />
))
AvatarFallback.displayName = "AvatarFallback"

export interface AvatarGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Maximum avatars rendered before the overflow counter appears. */
  max?: number
  /** Space between overlapping avatars in pixels. */
  spacing?: number
  children: React.ReactNode
}

/**
 * AvatarGroup — overlapping stack of avatars with a "+N" overflow counter.
 * The counter carries the hidden avatars' count to assistive tech; the group
 * itself is a list item-free plain container so it composes anywhere.
 */
const AvatarGroup = React.forwardRef<HTMLDivElement, AvatarGroupProps>(
  ({ max = 4, spacing = -10, className, style, children, ...props }, ref) => {
    const items = React.Children.toArray(children).filter(React.isValidElement)
    const visible = items.slice(0, Math.max(max, 0))
    const overflow = items.length - visible.length

    return (
      <div
        ref={ref}
        data-slot="avatar-group"
        data-overflow={overflow > 0 ? overflow : undefined}
        className={cn("flex items-center", className)}
        style={{ ...style, gap: spacing }}
        {...props}
      >
        {visible.map((child, i) => (
          <span
            key={i}
            data-slot="avatar-group-item"
            className="rounded-full ring-2 ring-background"
            style={{ zIndex: items.length - i }}
          >
            {child}
          </span>
        ))}
        {overflow > 0 ? (
          <span
            data-slot="avatar-group-overflow"
            aria-label={`${overflow} more`}
            role="img"
            className={cn(
              avatarVariants({ variant: "brand" }),
              "z-0 items-center justify-center rounded-full text-xs font-medium ring-2 ring-background"
            )}
          >
            +{overflow}
          </span>
        ) : null}
      </div>
    )
  }
)
AvatarGroup.displayName = "AvatarGroup"

export { Avatar, AvatarImage, AvatarFallback, AvatarGroup, avatarVariants }
